DROP TEMPORARY TABLE IF EXISTS _quiz_questions;
CREATE TEMPORARY TABLE _quiz_questions (
 seed_key VARCHAR(50) NOT NULL, question_order INT NOT NULL,
 difficulty ENUM('EASY','MEDIUM','HARD') NOT NULL,
 question_text VARCHAR(255) NOT NULL,
 option_a VARCHAR(255) NOT NULL, option_b VARCHAR(255) NOT NULL,
 option_c VARCHAR(255) NOT NULL, option_d VARCHAR(255) NOT NULL,
 correct_index TINYINT UNSIGNED NOT NULL,
 PRIMARY KEY(seed_key,question_order),
 CONSTRAINT chk_qb100_correct CHECK(correct_index BETWEEN 0 AND 3)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
