-- Resolve exact course/lesson titles to stable quiz IDs.
DROP TEMPORARY TABLE IF EXISTS _quiz_target_map;
CREATE TEMPORARY TABLE _quiz_target_map AS
SELECT t.seed_key,t.topic_code,c.id AS course_id,l.id AS lesson_id,q.id AS quiz_id,
       CONCAT(t.topic_code,@bank_suffix) AS bank_topic_code
FROM _quiz_targets t
JOIN Courses c ON c.title=t.course_title
JOIN Lessons l ON l.course_id=c.id AND l.title=t.lesson_title AND LOWER(l.type)='quiz'
JOIN Quizzes q ON q.lesson_id=l.id;
ALTER TABLE _quiz_target_map ADD PRIMARY KEY(seed_key), ADD UNIQUE KEY uq_qb100_quiz(quiz_id);

-- Hard validation before persisted data changes.
DROP TEMPORARY TABLE IF EXISTS _quiz_guard;
CREATE TEMPORARY TABLE _quiz_guard (name VARCHAR(100) PRIMARY KEY, ok TINYINT NOT NULL, CONSTRAINT chk_qb100_guard CHECK(ok=1));
INSERT INTO _quiz_guard SELECT 'all_51_targets_resolve', IF(COUNT(*)=51 AND COUNT(DISTINCT quiz_id)=51,1,0) FROM _quiz_target_map;
INSERT INTO _quiz_guard SELECT 'exactly_100_each', IF(COUNT(*)=51 AND MIN(cnt)=100 AND MAX(cnt)=100,1,0) FROM (SELECT seed_key,COUNT(*) cnt FROM _quiz_questions GROUP BY seed_key) x;
INSERT INTO _quiz_guard SELECT 'difficulty_40_40_20', IF(COUNT(*)=51 AND MIN(e)=40 AND MAX(e)=40 AND MIN(m)=40 AND MAX(m)=40 AND MIN(h)=20 AND MAX(h)=20,1,0) FROM (SELECT seed_key,SUM(difficulty='EASY') e,SUM(difficulty='MEDIUM') m,SUM(difficulty='HARD') h FROM _quiz_questions GROUP BY seed_key) x;
INSERT INTO _quiz_guard SELECT 'unique_question_stems', IF(COUNT(*)=51 AND MIN(cnt)=100 AND MIN(uniq)=100,1,0) FROM (SELECT seed_key,COUNT(*) cnt,COUNT(DISTINCT LOWER(TRIM(question_text))) uniq FROM _quiz_questions GROUP BY seed_key) x;

START TRANSACTION;

-- Unlimited retakes are represented by NULL max_attempts; application logic must treat NULL as unlimited.
UPDATE Quizzes q JOIN _quiz_target_map t ON t.quiz_id=q.id
SET q.description=NULL, q.max_attempts=NULL, q.passing_score=70.00, q.status='published', q.updated_at=CURRENT_TIMESTAMP(6);

-- Deactivate previous banks without deleting attempts or answers.
UPDATE Questions oldq JOIN _quiz_target_map t ON t.quiz_id=oldq.quiz_id SET oldq.active=b'0' WHERE oldq.topic_code<>t.bank_topic_code OR oldq.topic_code IS NULL;

-- Refresh rows from this bank version when the script is rerun.
UPDATE Questions q
JOIN _quiz_target_map t ON t.quiz_id=q.quiz_id AND q.topic_code=t.bank_topic_code
JOIN _quiz_questions s ON s.seed_key=t.seed_key AND s.question_order=q.display_order
SET q.question_text=s.question_text,
    q.options_json=CAST(JSON_ARRAY(s.option_a,s.option_b,s.option_c,s.option_d) AS CHAR CHARACTER SET utf8mb4),
    q.correct_answer=CAST(s.correct_index AS CHAR), q.question_type='single_choice',
    q.points=1.00, q.difficulty=s.difficulty, q.review_status='APPROVED',
    q.version=2, q.active=b'1', q.generation_source='MANUAL';

-- Insert missing rows for this bank version.
INSERT INTO Questions
 (quiz_id,question_text,options_json,correct_answer,question_type,points,display_order,topic_code,difficulty,review_status,version,active,generation_source,assignment_id)
SELECT t.quiz_id,s.question_text,CAST(JSON_ARRAY(s.option_a,s.option_b,s.option_c,s.option_d) AS CHAR CHARACTER SET utf8mb4),
       CAST(s.correct_index AS CHAR),'single_choice',1.00,s.question_order,t.bank_topic_code,
       s.difficulty,'APPROVED',2,b'1','MANUAL',NULL
FROM _quiz_questions s JOIN _quiz_target_map t ON t.seed_key=s.seed_key
WHERE NOT EXISTS (SELECT 1 FROM Questions q WHERE q.quiz_id=t.quiz_id AND q.topic_code=t.bank_topic_code AND q.display_order=s.question_order);

-- Replace only selection blueprints; attempts remain untouched.
DELETE b FROM Quiz_Blueprint_Items b JOIN _quiz_target_map t ON t.quiz_id=b.quiz_id;
INSERT INTO Quiz_Blueprint_Items (quiz_id,topic_code,difficulty,question_count,display_order,created_at,updated_at)
SELECT t.quiz_id,t.bank_topic_code,d.difficulty,d.question_count,d.display_order,CURRENT_TIMESTAMP(6),CURRENT_TIMESTAMP(6)
FROM _quiz_target_map t CROSS JOIN (
 SELECT 'EASY' difficulty,4 question_count,1 display_order UNION ALL
 SELECT 'MEDIUM',4,2 UNION ALL SELECT 'HARD',2,3) d;

-- Final persisted-state checks.
DELETE FROM _quiz_guard;
INSERT INTO _quiz_guard SELECT 'active_5100_valid_json', IF(COUNT(*)=5100 AND SUM(q.active=b'1')=5100 AND SUM(q.review_status='APPROVED')=5100 AND SUM(JSON_VALID(q.options_json))=5100 AND MIN(JSON_LENGTH(q.options_json))=4 AND MAX(JSON_LENGTH(q.options_json))=4,1,0) FROM Questions q JOIN _quiz_target_map t ON t.quiz_id=q.quiz_id AND q.topic_code=t.bank_topic_code;
INSERT INTO _quiz_guard SELECT '100_per_quiz_persisted', IF(COUNT(*)=51 AND MIN(cnt)=100 AND MAX(cnt)=100,1,0) FROM (SELECT t.quiz_id,COUNT(q.id) cnt FROM _quiz_target_map t LEFT JOIN Questions q ON q.quiz_id=t.quiz_id AND q.topic_code=t.bank_topic_code AND q.active=b'1' GROUP BY t.quiz_id) x;
INSERT INTO _quiz_guard SELECT '153_blueprint_rows', IF(COUNT(*)=153 AND SUM(b.question_count)=510,1,0) FROM Quiz_Blueprint_Items b JOIN _quiz_target_map t ON t.quiz_id=b.quiz_id;
COMMIT;

SELECT COUNT(DISTINCT t.quiz_id) quizzes_processed, COUNT(q.id) active_questions,
SUM(q.difficulty='EASY') easy_questions,SUM(q.difficulty='MEDIUM') medium_questions,SUM(q.difficulty='HARD') hard_questions,
@quiz_bank_started_at started_at,CURRENT_TIMESTAMP(6) completed_at
FROM _quiz_target_map t JOIN Questions q ON q.quiz_id=t.quiz_id AND q.topic_code=t.bank_topic_code AND q.active=b'1';

SELECT t.quiz_id,t.seed_key,c.title course_title,l.title lesson_title,COUNT(q.id) active_questions
FROM _quiz_target_map t JOIN Courses c ON c.id=t.course_id JOIN Lessons l ON l.id=t.lesson_id
JOIN Questions q ON q.quiz_id=t.quiz_id AND q.topic_code=t.bank_topic_code AND q.active=b'1'
GROUP BY t.quiz_id,t.seed_key,c.title,l.title ORDER BY t.quiz_id;

DROP TEMPORARY TABLE IF EXISTS _quiz_guard;
DROP TEMPORARY TABLE IF EXISTS _quiz_target_map;
DROP TEMPORARY TABLE IF EXISTS _quiz_questions;
DROP TEMPORARY TABLE IF EXISTS _quiz_targets;

SET SQL_SAFE_UPDATES = @qb100_previous_sql_safe_updates;
